mapper.update:
		UPDATE /* SQL_ID: AgentMapper.updateAgent */
               dtmeta.tb_meta_agent
		   SET agnt_nm					= #{agntNm}
             , agnt_model_id			= #{agntModelId}
             , medata_set_sttus_mtcd	= #{medataSetSttusMtcd}
             , agnt_desc				= #{agntDesc}
             , agnt_eng_nm				= #{agntEngNm}
             , agnt_eng_desc			= #{agntEngDesc}
             , agnt_tel_no				= #{agntTelNo}
             , agnt_hpage				= #{agntHpage}
             , agnt_amdr_id				= #{agntAmdrId}
             , agnt_amdr_nm				= #{agntAmdrNm}
             , agnt_amd_dt				= current_timestamp            
		 WHERE agnt_id 	    = #{agntId}

		UPDATE /* SQL_ID: AgentMapper.updateAgent */
               dtmeta.tb_meta_agent
		   SET medata_set_sttus_mtcd	= #{medataSetSttusMtcd}
             , agnt_amdr_id				= #{agntAmdrId}
             , agnt_amdr_nm				= #{agntAmdrNm}
             , agnt_amd_dt				= current_timestamp            
		 WHERE agnt_id 	    = #{agntId}

mapper.delete:
DELETE /* SQL_ID: AgentMapper.deleteAgent */
  FROM dtmeta.tb_meta_agent
 WHERE agnt_id = #{agntId}

mapper.select:
SELECT EXISTS ( /* SQL_ID: AgentMapper.selectMetaDataByAgntModelId */
	SELECT 1 
	FROM dtmeta.tb_meta_data
	WHERE medata_val = #{agntId}
	AND val_model_id = #{agntModelId}
)

SELECT EXISTS ( /* SQL_ID: AgentMapper.selectMetaCodeBySttusMtcd */
	SELECT 1 
	FROM dtmeta.tb_portal_code
	WHERE mtcd = #{medataSetSttusMtcd}
	AND mtcd_grp_id = 'MCG00001'
)
